// Gera tests/golden/eval_bun.tsv: eval direto e indireto, `with`, `delete` de variável, `new Function`,
// `arguments` mapeado, binding imutável de função nomeada, var/let/class globais e `eval` como nome, medidos no
// bun 1.4.2. Cada programa roda como script (vm.runInThisContext, sem o invólucro de módulo do bun), num processo
// novo, e grava o texto em `globalThis.R`. Colunas: a fonte (JSON) e o valor de `R` (JSON).
// Uso: bun scripts/gen-eval-golden.js > tests/golden/eval_bun.tsv
const fs = require("fs");
