// ---- Execução.
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eval-golden-"));
const runner = path.join(dir, "runner.js");
fs.writeFileSync(
  runner,
  [
    "const vm = require('vm');",
    "const fs = require('fs');",
    "const src = fs.readFileSync(process.argv[2], 'utf8');",
    "try { vm.runInThisContext(src, { filename: 'eval_case.js' }); } catch (e) { process.stdout.write('\\u0002' + String(e && e.name) + ': ' + String(e && e.message) + '\\n'); process.exit(0); }",
    "setTimeout(() => { process.stdout.write('\\u0001' + JSON.stringify(globalThis.R === undefined ? '<undefined>' : String(globalThis.R)) + '\\n'); }, 0);",
  ].join("\n"),
);
const file = path.join(dir, "case.js");
const seen = new Set();
let kept = 0;
let dropped = 0;
const { usesHostApi } = require("./host-api.js");
// O porte é só o motor: nada de programa que dependa de API de host do bun (ver host-api.js).
programs.splice(0, programs.length, ...programs.filter((p) => !usesHostApi(p)));
for (const body of programs) {
  if (seen.has(body)) continue;
  seen.add(body);
  fs.writeFileSync(file, body);
  const result = spawnSync(process.execPath, [runner, file], { encoding: "utf8", cwd: dir, timeout: 10000 });
  const marked = (result.stdout || "").split("\n").find(line => line.startsWith("\u0001"));
  if (!marked) {
    dropped++;
    continue;
  }
  const value = JSON.parse(marked.slice(1));
  if (value.includes(dir) || /\/home\/|\/tmp\/|\/Users\//.test(value)) {
    dropped++;
    continue;
  }
  kept++;
  emitRow(JSON.stringify(body) + "\t" + JSON.stringify(value));
}
process.stderr.write(`mantidos ${kept}, descartados ${dropped}\n`);
fs.rmSync(dir, { recursive: true, force: true });
